export default (rows) => rows.map((r) => {
  const premium = Number(r.premium);
  const ask = Number(r.ask_side_premium);
  const bid = Number(r.bid_side_premium);
  const side = ask > bid ? 'ask' : bid > ask ? 'bid' : 'mixed';
  const ratio = Number(r.volume_oi_ratio);
  const money = Math.round(premium).toLocaleString('en-US');
  return {
    ticker: r.ticker,
    kind: r.kind,
    strike: r.strike,
    expiry: r.expiry,
    premium,
    side,
    volume_oi: ratio,
    observed_at: r.observed_at,
    summary:
      `${r.ticker} ${r.kind} $${r.strike} expiring ${r.expiry}: ` +
      `$${money} of premium, filled on the ${side} side, ` +
      `volume is ${ratio.toFixed(2)} of open interest, ` +
      `rule ${r.alert_rule}` +
      (r.sweep === 'yes' ? ', swept across exchanges' : '')
  };
})
